'use client';

import Link from 'next/link';
import { useEffect, useMemo, useRef, useState } from 'react';
import { Container } from '@/components/Container';
import { ContentAssetBackground } from '@/components/ContentAssetBackground';
import { SocialCinematicIntro } from '@/components/SocialCinematicIntro';
import { RichPostBody, SocialLinkField } from '@/components/SocialRichContent';
import { useAuth } from '@/hooks/useAuth';
import { getSupabaseClient } from '@/lib/supabase';
import { rankSocialPosts } from '@/lib/social-feed';
import { FaArrowRight, FaBasketball, FaBell, FaBolt, FaBookmark, FaCheck, FaComment, FaCompass, FaFire, FaHeart, FaImage, FaMagnifyingGlass, FaPeopleGroup, FaPlay, FaPlus, FaShareNodes, FaTrash, FaUser, FaUserGroup, FaVideo, FaXmark, FaBars, FaHouse, FaGear } from 'react-icons/fa6';

const reactions = [
  { type: 'bucket', emoji: '🏀', label: 'Bucket' }, { type: 'heat', emoji: '🔥', label: 'Heat' },
  { type: 'strong', emoji: '💪', label: 'Tough' }, { type: 'locked', emoji: '🔒', label: 'Locked' },
  { type: 'money', emoji: '🎯', label: 'Pure' }, { type: 'watch', emoji: '👀', label: 'Seen' },
  { type: 'champ', emoji: '🏆', label: 'Champ' },
];
type Author = { id?: string; display_name: string | null; username: string | null; avatar_url?: string | null; role?: string | null; is_vip?: boolean | null; vip_label?: string | null; rep?: number; level?: number };
type Comment = { id: string; post_id: string; author_id: string; body: string; created_at: string; author?: Author };
type Reaction = { user_id: string; post_id: string; type: string };
type Post = { id: string; author_id: string; body: string; media_urls: string[]; created_at: string; author?: Author; comments?: Comment[]; reactions?: Reaction[] };
type Story = { id: string; body: string | null; media_url?: string | null; expires_at: string; author_id?: string; author?: Author };
type Community = { id: string; name: string; slug: string; description: string | null; community_type: string | null };
type Tab = 'feed' | 'discover' | 'runs' | 'highlights' | 'communities' | 'messages' | 'notifications';
const tabs: Array<{ id: Tab; label: string; icon: React.ReactNode }> = [
  { id: 'feed', label: 'Feed', icon: <FaBolt /> }, { id: 'discover', label: 'Discover', icon: <FaCompass /> },
  { id: 'runs', label: 'Runs', icon: <FaBasketball /> }, { id: 'highlights', label: 'Highlights', icon: <FaPlay /> },
  { id: 'communities', label: 'Communities', icon: <FaPeopleGroup /> }, { id: 'messages', label: 'Messages', icon: <FaComment /> },
  { id: 'notifications', label: 'Notifications', icon: <FaHeart /> },
];

type Filter = 'all' | 'following' | 'trending' | 'runs' | 'highlights' | 'players' | 'teams' | 'communities';

export default function SocialPage() {
  const { user } = useAuth();
  const [view, setView] = useState<string | null>(null);
  const supabase = useMemo(() => getSupabaseClient(), []);
  const [posts, setPosts] = useState<Post[]>([]); const [stories, setStories] = useState<Story[]>([]); const [currentProfile, setCurrentProfile] = useState<Author | null>(null);
  const [suggestedProfiles, setSuggestedProfiles] = useState<Author[]>([]); const [communities, setCommunities] = useState<Community[]>([]);
  const [following, setFollowing] = useState<string[]>([]); const [saved, setSaved] = useState<string[]>([]); const [level, setLevel] = useState<{ level: number; xp: number } | null>(null);
  const [loading, setLoading] = useState(true); const [error, setError] = useState('');
  const [body, setBody] = useState(''); const [linkInput, setLinkInput] = useState(''); const [mediaFile, setMediaFile] = useState<File | null>(null); const [mediaPreview, setMediaPreview] = useState('');
  const [story, setStory] = useState(''); const [storyFile, setStoryFile] = useState<File | null>(null); const [storyPreview, setStoryPreview] = useState('');
  const [filter, setFilter] = useState<Filter>('all'); const [tab, setTab] = useState<Tab>('feed'); const [search, setSearch] = useState('');
  const [openComments, setOpenComments] = useState<string | null>(null); const [comment, setComment] = useState<Record<string, string>>({});
  const [reactionBurst, setReactionBurst] = useState<Record<string, string>>({});
  const [storyIndex, setStoryIndex] = useState<number | null>(null); const [composerOpen, setComposerOpen] = useState(false); const [platformMenuOpen, setPlatformMenuOpen] = useState(false);
  const [publishing, setPublishing] = useState(false); const [publishingStory, setPublishingStory] = useState(false);
  const mediaInputRef = useRef<HTMLInputElement | null>(null); const storyInputRef = useRef<HTMLInputElement | null>(null);
  useEffect(() => { setView(new URLSearchParams(window.location.search).get('view')); }, []);

  const signInForSocial = () => { window.location.href = '/auth/sign-in?redirect=/social'; };
  const openComposer = () => { if (!user) { signInForSocial(); return; } setComposerOpen(true); };
  const awardRep = async (amount: number, reason: 'quality_content' | 'meaningful_engagement' | 'community_contribution', sourceType: string, sourceId?: string) => {
    if (!supabase || !user || !sourceId) return;
    const { data } = await supabase.rpc('award_xp', { target_profile_id: user.id, xp_amount: amount, xp_reason: reason, source_kind: sourceType, source_uuid: sourceId } as never);
    const level = data as unknown as { xp?: number; level?: number } | null;
    if (level?.xp !== undefined) setCurrentProfile((current) => current ? { ...current, rep: level.xp, level: level.level ?? current.level } : current);
  };
  const trackActivity = async (activity_type: string, entity_type?: string, entity_id?: string, metadata: Record<string, unknown> = {}) => {
    if (!supabase || !user) return;
    await supabase.from('user_activity').insert({ profile_id: user.id, activity_type, entity_type: entity_type ?? null, entity_id: entity_id ?? null, metadata } as never);
  };



  const load = async () => {
    if (!supabase) { setLoading(false); setError('Social services are not configured.'); return; }
    setLoading(true); setError('');
    try {
      const { data: basePosts, error: postsError } = await supabase.from('posts').select('id,author_id,body,media_urls,created_at').eq('status', 'published').order('created_at', { ascending: false }).limit(100);
      if (postsError) throw postsError;
      const safePosts = (basePosts ?? []) as unknown as Array<Omit<Post, 'author' | 'comments' | 'reactions'>>;
      const postIds = safePosts.map((p) => p.id);
      const [commentsResult, reactionsResult, storiesResult, followsResult, savedResult, levelResult, currentProfileResult, suggestedResult, communitiesResult] = await Promise.all([
        postIds.length ? supabase.from('comments').select('id,post_id,author_id,body,created_at').in('post_id', postIds).order('created_at', { ascending: true }) : Promise.resolve({ data: [], error: null }),
        postIds.length ? supabase.from('reactions').select('post_id,user_id,type').in('post_id', postIds) : Promise.resolve({ data: [], error: null }),
        supabase.from('stories').select('id,body,media_url,expires_at,author_id').gt('expires_at', new Date().toISOString()).order('created_at', { ascending: false }).limit(20),
        user ? supabase.from('follows').select('following_id').eq('follower_id', user.id) : Promise.resolve({ data: [], error: null }),
        user ? supabase.from('saved_posts').select('post_id').eq('profile_id', user.id) : Promise.resolve({ data: [], error: null }),
        user ? supabase.from('user_levels').select('level,xp').eq('profile_id', user.id).maybeSingle() : Promise.resolve({ data: null, error: null }),
        user ? supabase.from('profiles').select('id,display_name,username,avatar_url,role,is_vip,vip_label').eq('id', user.id).maybeSingle() : Promise.resolve({ data: null, error: null }),
        supabase.from('profiles').select('id,display_name,username,avatar_url,role,is_vip,vip_label').eq('is_active', true).eq('profile_visibility', 'public').order('created_at', { ascending: false }).limit(12),
        supabase.from('communities').select('id,name,slug,description,community_type').eq('privacy', 'public').order('created_at', { ascending: false }).limit(6),
      ]);
      const comments = (commentsResult.data ?? []) as unknown as Comment[]; const storyRows = (storiesResult.data ?? []) as unknown as Story[];
      const suggestedRows = (suggestedResult.data ?? []) as unknown as Array<Author & { id: string }>;
      const identityIds = [...new Set([...safePosts.map((p) => p.author_id), ...comments.map((item) => item.author_id), ...storyRows.map((item) => item.author_id).filter((id): id is string => Boolean(id)), ...suggestedRows.map((item) => item.id), ...(user ? [user.id] : [])])];
      const authorsResult = identityIds.length ? await supabase.from('profiles').select('id,display_name,username,avatar_url,role,is_vip,vip_label').in('id', identityIds) : { data: [], error: null };
      const authors = (authorsResult.data ?? []) as unknown as Array<Author & { id: string }>;
      const levelIds = authors.map((author) => author.id);
      const socialLevelsResult = levelIds.length ? await supabase.from('user_levels').select('profile_id,level,xp').in('profile_id', levelIds) : { data: [], error: null };
      const socialLevelMap = new Map(((socialLevelsResult.data ?? []) as Array<{profile_id:string;level:number;xp:number}>).map((row) => [row.profile_id, row]));
      const enrichedAuthors = authors.map((author) => ({ ...author, rep: socialLevelMap.get(author.id)?.xp ?? 0, level: socialLevelMap.get(author.id)?.level ?? 1 }));
      const authorMap = new Map(enrichedAuthors.map((a) => [a.id, a]));
      const reactionsData = (reactionsResult.data ?? []) as unknown as Reaction[];
      setPosts(safePosts.map((p) => ({ ...p, author: authorMap.get(p.author_id), comments: comments.filter((c) => c.post_id === p.id).map((c) => ({ ...c, author: authorMap.get(c.author_id) })), reactions: reactionsData.filter((r) => r.post_id === p.id) })));
      setStories(storyRows.map((s) => ({ ...s, author: authorMap.get(s.author_id ?? '') })));
      setCurrentProfile(user ? ({ ...((currentProfileResult.data as Author | null) ?? {}), ...(authorMap.get(user.id) ?? {}) } as Author) : null);
      setFollowing(((followsResult.data ?? []) as Array<{ following_id: string }>).map((r) => r.following_id));
      setSaved(((savedResult.data ?? []) as Array<{ post_id: string }>).map((r) => r.post_id));
      setSuggestedProfiles(suggestedRows.map((profile) => authorMap.get(profile.id) ?? profile).filter((profile) => profile.id !== user?.id).sort((a,b) => (b.rep ?? 0) - (a.rep ?? 0)).slice(0,6));
      setCommunities((communitiesResult.data ?? []) as unknown as Community[]);
      const levelData = levelResult.data as { level?: number; xp?: number } | null;
      setLevel(levelData?.level ? { level: levelData.level, xp: levelData.xp ?? 0 } : null);
    } catch (loadError) { console.error('Unable to load the social timeline', loadError); setError(loadError instanceof Error ? loadError.message : 'We could not load the social timeline.'); setPosts([]); }
    finally { setLoading(false); }
  };
  useEffect(() => { void load(); }, [supabase, user?.id]);
  useEffect(() => { if (!supabase) return; const channel = supabase.channel('rcl-social-live').on('postgres_changes', { event: '*', schema: 'public', table: 'posts' }, () => void load()).on('postgres_changes', { event: '*', schema: 'public', table: 'comments' }, () => void load()).on('postgres_changes', { event: '*', schema: 'public', table: 'reactions' }, () => void load()).on('postgres_changes', { event: '*', schema: 'public', table: 'stories' }, () => void load()).subscribe(); return () => { void supabase.removeChannel(channel); }; }, [supabase, user?.id]);
  useEffect(() => { if (!mediaFile) { setMediaPreview(''); return; } const url = URL.createObjectURL(mediaFile); setMediaPreview(url); return () => URL.revokeObjectURL(url); }, [mediaFile]);
  useEffect(() => { if (!storyFile) { setStoryPreview(''); return; } const url = URL.createObjectURL(storyFile); setStoryPreview(url); return () => URL.revokeObjectURL(url); }, [storyFile]);

  const uploadMedia = async (file: File, folder: 'posts' | 'stories') => {
    if (!supabase || !user) throw new Error('Please sign in to upload media.');
    if (!file.type.startsWith('image/') && !file.type.startsWith('video/')) throw new Error('Please choose an image or video file.');
    if (file.size > 50 * 1024 * 1024) throw new Error('Media must be 50MB or smaller.');
    const extension = file.name.split('.').pop()?.toLowerCase() || (file.type.startsWith('video/') ? 'mp4' : 'jpg');
    const path = `${user.id}/${folder}/${Date.now()}-${crypto.randomUUID()}.${extension}`;
    const { error: uploadError } = await supabase.storage.from('media').upload(path, file, { upsert: false, contentType: file.type, cacheControl: '3600' });
    if (uploadError) throw uploadError;
    return supabase.storage.from('media').getPublicUrl(path).data.publicUrl;
  };

  const createPost = async (e: React.FormEvent) => {
    e.preventDefault(); if (!supabase || !user) { signInForSocial(); return; } if (!body.trim() && !mediaFile && !linkInput.trim()) return;
    setPublishing(true); setError('');
    try { const composedBody = [body.trim(), linkInput.trim()].filter(Boolean).join('\n'); const mediaUrl = mediaFile ? await uploadMedia(mediaFile, 'posts') : ''; const { data, error: insertError } = await supabase.from('posts').insert({ author_id: user.id, body: composedBody, media_urls: mediaUrl ? [mediaUrl] : [], status: 'published' } as never).select('id,author_id,body,media_urls,created_at').single(); if (insertError) throw insertError; setBody(''); setLinkInput(''); setMediaFile(null); setComposerOpen(false); const createdId = (data as { id?: string } | null)?.id; void trackActivity('post_created', 'post', createdId); if (createdId) void awardRep(20, 'quality_content', 'post', createdId); if (data) setPosts((current) => [{ ...(data as unknown as Post), author: currentProfile ?? { id: user.id, display_name: 'RCL Member', username: null, avatar_url: null, role: null }, comments: [], reactions: [] }, ...current]); }
    catch (publishError) { const message = publishError instanceof Error ? publishError.message : (publishError && typeof publishError === 'object' && 'message' in publishError ? String((publishError as { message?: unknown }).message ?? '') : ''); console.error('Unable to publish social post', publishError); setError(message || 'We could not publish that post.'); } finally { setPublishing(false); }
  };
  const createStory = async (e: React.FormEvent) => {
    e.preventDefault(); if (!supabase || !user) { signInForSocial(); return; } if (!story.trim() && !storyFile) return; setPublishingStory(true); setError('');
    try { const mediaUrl = storyFile ? await uploadMedia(storyFile, 'stories') : null; const type = mediaUrl ? (storyFile?.type.startsWith('video/') ? 'video' : 'photo') : 'text'; const { data, error: storyError } = await supabase.from('stories').insert({ author_id: user.id, story_type: type, body: story.trim() || null, media_url: mediaUrl, audience: 'public' } as never).select('id,body,media_url,expires_at,author_id').single(); if (storyError) throw storyError; if (data) setStories((current) => [{ ...(data as unknown as Story), author: currentProfile ?? { id: user.id, display_name: 'RCL Member', username: null } }, ...current]); setStory(''); setStoryFile(null); }
    catch (storyError) { const message = storyError instanceof Error ? storyError.message : (storyError && typeof storyError === 'object' && 'message' in storyError ? String((storyError as { message?: unknown }).message ?? '') : ''); console.error('Unable to publish social story', storyError); setError(message || 'We could not publish that story.'); } finally { setPublishingStory(false); }
  };
  const react = async (postId: string, type: string) => {
    if (!supabase || !user) { signInForSocial(); return; }
    setReactionBurst((current) => ({ ...current, [postId]: type })); window.setTimeout(() => setReactionBurst((current) => { const next = { ...current }; if (next[postId] === type) delete next[postId]; return next; }), 760);
    const post = posts.find((p) => p.id === postId); const existing = post?.reactions?.find((r) => r.user_id === user.id); const nextType = existing?.type === type ? null : type;
    setPosts((current) => current.map((p) => p.id !== postId ? p : { ...p, reactions: nextType ? [...(p.reactions ?? []).filter((r) => r.user_id !== user.id), { post_id: postId, user_id: user.id, type: nextType }] : (p.reactions ?? []).filter((r) => r.user_id !== user.id) }));
    const removed = existing ? await supabase.from('reactions').delete().eq('post_id', postId).eq('user_id', user.id) : { error: null }; if (removed.error) { setError(removed.error.message); void load(); return; }
    if (nextType) { void trackActivity('reaction', 'post', postId, { reaction_type: nextType }); const added = await supabase.from('reactions').insert({ post_id: postId, user_id: user.id, type: nextType } as never); if (added.error) { setError(added.error.message); void load(); } else { void awardRep(2, 'meaningful_engagement', 'reaction', postId); } }
  };
  const toggleSave = async (postId: string) => {
    if (!supabase || !user) { signInForSocial(); return; } const isSaved = saved.includes(postId); setSaved((current) => isSaved ? current.filter((id) => id !== postId) : [...current, postId]);
    const result = isSaved ? await supabase.from('saved_posts').delete().eq('profile_id', user.id).eq('post_id', postId) : await supabase.from('saved_posts').insert({ profile_id: user.id, post_id: postId } as never); if (result.error) { setSaved((current) => isSaved ? [...current, postId] : current.filter((id) => id !== postId)); setError(result.error.message); } else { void trackActivity(isSaved ? 'save_removed' : 'save_added', 'post', postId); }
  };
  const toggleFollow = async (profileId: string) => {
    if (!supabase || !user) { signInForSocial(); return; } if (profileId === user.id) return; const isFollowing = following.includes(profileId); setFollowing((current) => isFollowing ? current.filter((id) => id !== profileId) : [...current, profileId]);
    const result = isFollowing ? await supabase.from('follows').delete().eq('follower_id', user.id).eq('following_id', profileId) : await supabase.from('follows').insert({ follower_id: user.id, following_id: profileId } as never); if (result.error) { setFollowing((current) => isFollowing ? [...current, profileId] : current.filter((id) => id !== profileId)); setError(result.error.message); } else { void trackActivity(isFollowing ? 'unfollow' : 'follow', 'profile', profileId); if (!isFollowing) void awardRep(3, 'community_contribution', 'follow', profileId); }
  };
  const addComment = async (postId: string) => {
    if (!supabase || !user) { signInForSocial(); return; } const text = comment[postId]?.trim(); if (!text) return; setComment((current) => ({ ...current, [postId]: '' }));
    const optimistic: Comment = { id: `local-${Date.now()}`, post_id: postId, author_id: user.id, body: text, created_at: new Date().toISOString(), author: currentProfile ?? { id: user.id, display_name: 'RCL Member', username: null } }; setPosts((current) => current.map((p) => p.id === postId ? { ...p, comments: [...(p.comments ?? []), optimistic] } : p));
    const { error: commentError } = await supabase.from('comments').insert({ post_id: postId, author_id: user.id, body: text, parent_id: null } as never); if (commentError) { setError(commentError.message); void load(); } else { void trackActivity('comment', 'post', postId); void awardRep(5, 'meaningful_engagement', 'comment', postId); }
  };
  const sharePost = async (post: Post) => { const url = `${window.location.origin}/social#post-${post.id}`; try { if (navigator.share) { await navigator.share({ title: 'Rich City Social', text: post.body.slice(0, 120), url }); void trackActivity('share', 'post', post.id); } else { await navigator.clipboard.writeText(url); void trackActivity('share', 'post', post.id); setError('Post link copied to your clipboard.'); window.setTimeout(() => setError(''), 2200); } } catch { /* cancelled */ } };
  const viewStory = async (index: number) => { setStoryIndex(index); const item = stories[index]; if (supabase && user && item) { void trackActivity('story_view', 'story', item.id); await supabase.from('story_views').upsert({ story_id: item.id, viewer_id: user.id } as never); } };
  const deletePost = async (postId: string) => { if (!supabase || !user) return; if (!window.confirm('Delete this post?')) return; const result = await supabase.from('posts').delete().eq('id', postId).eq('author_id', user.id); if (result.error) { setError(result.error.message); return; } setPosts((current) => current.filter((p) => p.id !== postId)); };

  const visiblePosts = useMemo(() => {
    const query = search.trim().toLowerCase();
    const filtered = posts.filter((post) => {
      const text = post.body.toLowerCase();
      const author = `${post.author?.display_name ?? ''} ${post.author?.username ?? ''}`.toLowerCase();
      if (query && !text.includes(query) && !author.includes(query)) return false;
      if (filter === 'following') return following.includes(post.author_id) || post.author_id === user?.id;
      if (filter === 'trending') return true;
      if (filter === 'runs') return /run|pickup|court|hooping|5v5|3v3|1v1/.test(text);
      if (filter === 'highlights') return (post.media_urls?.length ?? 0) > 0 || /highlight|bucket|dunk|game winner/.test(text);
      if (filter === 'players') return post.author?.role === 'player' || /player|guard|forward|center/.test(text);
      if (filter === 'teams') return /team|roster|squad|club/.test(text);
      if (filter === 'all') return true;
      return /community|804|richmond|neighborhood/.test(text);
    });

    if (filter === 'trending') return [...filtered].sort((a,b) => (((b.reactions?.length ?? 0) * 3) + ((b.comments?.length ?? 0) * 5) + Math.max(0, 72 - ((Date.now() - new Date(b.created_at).getTime()) / 3600000))) - (((a.reactions?.length ?? 0) * 3) + ((a.comments?.length ?? 0) * 5) + Math.max(0, 72 - ((Date.now() - new Date(a.created_at).getTime()) / 3600000))));
    if (filter !== 'all' || search.trim()) return filtered;

    return rankSocialPosts(filtered, {
      userId: user?.id,
      following,
    });
  }, [posts, filter, search, following, user?.id]);
  const viewPosts = useMemo(() => {
    if (view === 'saved') return visiblePosts.filter((post) => saved.includes(post.id));
    if (view === 'media') return visiblePosts.filter((post) => (post.media_urls?.length ?? 0) > 0);
    if (view === 'highlights') return visiblePosts.filter((post) => (post.media_urls?.length ?? 0) > 0 || /highlight|bucket|dunk|game winner/i.test(post.body));
    return visiblePosts;
  }, [visiblePosts, saved, view]);
  const trending = useMemo(() => { const words = new Map<string, number>(); posts.forEach((p) => p.body.toLowerCase().split(/\s+/).forEach((word) => { const clean = word.replace(/[^a-z0-9#]/g, ''); if (clean.length >= 4 && !['that', 'this', 'with', 'from', 'game', 'just', 'have', 'your'].includes(clean)) words.set(clean, (words.get(clean) ?? 0) + 1); })); return [...words.entries()].sort((a, b) => b[1] - a[1]).slice(0, 5); }, [posts]);
  const selectTab = (next: Tab) => { setTab(next); if (next === 'discover') { setSearch(''); setFilter('players'); } if (next === 'highlights') setFilter('highlights'); };

  return <><SocialCinematicIntro /><main className="rcl-social-page relative min-h-screen bg-[#05080d] text-white pb-20 lg:pb-0"><ContentAssetBackground assetKey="social.cover" opacity={0.055} className="rcl-social-cover" /><div className="relative z-10">
    <header className="rcl-social-header rcl-social-premium-header sticky top-0 z-40"><Container maxWidth="xl" className="flex h-16 items-center gap-3"><button type="button" onClick={() => setPlatformMenuOpen(true)} aria-label="Open Rich City League menu" className="rcl-social-icon-button"><FaBars /></button><Link href="/social" className="rcl-social-wordmark"><b>RCL</b><span>SOCIAL</span></Link><div className="relative min-w-0 flex-1"><FaMagnifyingGlass className="absolute left-4 top-1/2 -translate-y-1/2 text-white/25" /><input value={search} onChange={(e) => { setSearch(e.target.value); setTab('feed'); }} placeholder="Search people, teams, topics…" className="rcl-social-search w-full py-2.5 pl-10 pr-4 text-sm outline-none" /></div>{user ? <button onClick={openComposer} className="rcl-social-create hidden sm:inline-flex"><FaPlus /> Create</button> : <Link href="/auth/sign-in?redirect=/social" className="rcl-social-create hidden sm:inline-flex">Sign in</Link>}</Container></header>
    <Container maxWidth="xl" className="py-4 sm:py-5"><div className="grid gap-5 lg:grid-cols-[220px_minmax(0,1fr)_300px]">
      <aside className="hidden lg:block"><nav className="sticky top-24 space-y-1">{tabs.map((item) => item.id === 'runs' ? <Link key={item.id} href="/runs" className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-xs font-bold text-white/55 hover:bg-white/[.05] hover:text-white">{item.icon}<span>{item.label}</span></Link> : item.id === 'communities' ? <Link key={item.id} href="/communities" className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-xs font-bold text-white/55 hover:bg-white/[.05] hover:text-white">{item.icon}<span>{item.label}</span></Link> : item.id === 'messages' ? <Link key={item.id} href="/messages" className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-xs font-bold text-white/55 hover:bg-white/[.05] hover:text-white">{item.icon}<span>{item.label}</span></Link> : item.id === 'notifications' ? <Link key={item.id} href="/notifications" className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-xs font-bold text-white/55 hover:bg-white/[.05] hover:text-white">{item.icon}<span>{item.label}</span></Link> : <button key={item.id} onClick={() => selectTab(item.id)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-xs font-bold transition ${tab === item.id ? 'bg-rcl-orange text-black' : 'text-white/55 hover:bg-white/[.05] hover:text-white'}`}>{item.icon}<span>{item.label}</span></button>)}<div className="my-4 border-t border-white/10" /><Link href="/lab" className="flex items-center gap-3 rounded-xl px-3 py-3 text-xs font-bold text-white/55 hover:bg-white/[.05] hover:text-white"><FaBasketball /> The Lab</Link><Link href="/games" className="flex items-center gap-3 rounded-xl px-3 py-3 text-xs font-bold text-white/55 hover:bg-white/[.05] hover:text-white"><FaPlay /> Game Center</Link></nav></aside>
      <div className="min-w-0">{tab === 'feed' ? <>
        <div className="rcl-feed-mode"><button onClick={() => setFilter('all')} className={filter==='all'?'active':''}>For You</button><button onClick={() => setFilter('following')} className={filter==='following'?'active':''}>Following</button><button onClick={() => setFilter('trending')} className={filter==='trending'?'active':''}>Trending</button></div><section className="rcl-story-rail mb-4 border-b border-white/10 pb-4">
          <div className="flex gap-3 overflow-x-auto px-1 pb-1 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
            {user && <Link href={`/social/profile/${user.id}`} className="w-[72px] shrink-0 text-center" aria-label="View my public profile"><span className="mx-auto grid h-16 w-16 place-items-center overflow-hidden rounded-full border-2 border-rcl-blue bg-[#101722]"><Avatar author={currentProfile ?? { display_name: 'RCL Member', username: null }} /></span><span className="mt-2 block truncate text-[9px] font-bold text-white/70">My profile</span></Link>}
            {user ? <form onSubmit={createStory} className="w-[72px] shrink-0 text-center">
              <button type="button" onClick={() => storyInputRef.current?.click()} className="relative mx-auto grid h-16 w-16 place-items-center overflow-hidden rounded-full border-2 border-dashed border-rcl-orange bg-white/[.04]" aria-label="Create story">
                {storyPreview ? (storyFile?.type.startsWith('video/') ? <video src={storyPreview} muted className="h-full w-full object-cover" /> : <img src={storyPreview} alt="Story preview" className="h-full w-full object-cover" />) : <Avatar author={currentProfile ?? { display_name: 'RCL Member', username: null }} />}
                <span className="absolute bottom-0 right-0 grid h-6 w-6 place-items-center rounded-full border-2 border-[#05080d] bg-rcl-orange text-[10px] text-black"><FaPlus /></span>
              </button>
              <input ref={storyInputRef} type="file" accept="image/*,video/*" onChange={(e) => setStoryFile(e.target.files?.[0] ?? null)} className="hidden" />
              <input value={story} onChange={(e) => setStory(e.target.value)} maxLength={240} placeholder="Add text" aria-label="Story text" className="mt-2 w-full bg-transparent text-center text-[10px] text-white/55 outline-none placeholder:text-white/30" />
              {(story.trim() || storyFile) && <button disabled={publishingStory} className="mt-1 text-[8px] font-black uppercase tracking-wider text-rcl-orange disabled:opacity-30">{publishingStory ? 'Posting…' : 'Share'}</button>}
              {!story.trim() && !storyFile && <span className="mt-1 block truncate text-[9px] font-bold text-white/70">Your story</span>}
            </form> : <button onClick={signInForSocial} className="w-[72px] shrink-0 text-center"><span className="mx-auto grid h-16 w-16 place-items-center rounded-full border-2 border-dashed border-rcl-orange/50 bg-white/[.04] text-rcl-orange"><FaPlus /></span><span className="mt-2 block text-[9px] font-bold text-white/70">Add story</span></button>}
            {(view === 'stories' ? stories.filter((item) => item.author_id === user?.id) : stories).map((item, index) => <div key={item.id} className="w-[72px] shrink-0 text-center"><button onClick={() => void viewStory(index)} className="w-full text-center">
              <span className="relative mx-auto block h-16 w-16 rounded-full bg-gradient-to-br from-rcl-orange via-rcl-gold to-rcl-orange p-[2px]">
                <span className="block h-full w-full overflow-hidden rounded-full border-2 border-[#05080d] bg-[#101722]">
                  {item.media_url ? (isVideoUrl(item.media_url) ? <video src={item.media_url} muted playsInline className="h-full w-full object-cover" /> : <img src={item.media_url} alt="" className="h-full w-full object-cover" />) : <span className="grid h-full w-full place-items-center"><Avatar author={item.author} /></span>}
                </span>
              </span>
              </button><Link href={`/social/profile/${item.author_id}`} className="mt-2 block truncate text-[9px] font-bold text-white/70 hover:text-rcl-orange">{item.author?.display_name ?? 'RCL Player'}</Link></div>)}
            {!stories.length && <div className="rcl-story-empty">Your city&apos;s stories will appear here.</div>}
          </div>
        </section>
        <section className="rcl-quick-composer mb-5"><div className="flex gap-3"><button onClick={openComposer} aria-label="Open post composer"><Avatar author={user ? currentProfile ?? { display_name: 'RCL Member', username: null } : { display_name: 'Guest', username: null }} /></button><button onClick={openComposer} className="flex-1 rounded-2xl border border-white/10 bg-black/20 px-4 py-3 text-left text-sm text-white/35 hover:border-rcl-orange/30">What is happening on the court?</button></div><div className="mt-3 flex flex-wrap gap-2"><QuickAction icon={<FaImage />} label="Photo / Video" onClick={openComposer} /><QuickAction icon={<FaBasketball />} label="Create a Run" onClick={() => { window.location.href = '/runs'; }} /><QuickAction icon={<FaUserGroup />} label="Tag Player" onClick={() => { window.location.href = '/players'; }} /><QuickAction icon={<FaFire />} label="Share Highlight" onClick={() => { setTab('feed'); setFilter('highlights'); }} /></div></section>
        {loading ? <LoadingFeed /> : visiblePosts.length ? viewPosts.map((post) => <PostCard key={post.id} post={post} userId={user?.id} following={following.includes(post.author_id)} saved={saved.includes(post.id)} openComments={openComments === post.id} comment={comment[post.id] ?? ''} onCommentChange={(value) => setComment((current) => ({ ...current, [post.id]: value }))} onToggleComments={() => setOpenComments((current) => current === post.id ? null : post.id)} onComment={() => void addComment(post.id)} onReact={(type) => void react(post.id, type)} reactionBurst={reactionBurst[post.id] ?? null} onSave={() => void toggleSave(post.id)} onShare={() => void sharePost(post)} onFollow={() => void toggleFollow(post.author_id)} onDelete={post.author_id === user?.id ? () => void deletePost(post.id) : undefined} />)  : <SocialDiscoveryEmpty search={search} profiles={suggestedProfiles} communities={communities} following={following} onFollow={(id) => void toggleFollow(id)} onCreate={openComposer} />}
      </> : <section className="rounded-3xl border border-white/10 bg-white/[.03] p-6 sm:p-8"><div className="max-w-2xl"><span className="inline-flex rounded-full bg-rcl-orange/10 px-3 py-1 text-[9px] font-black uppercase tracking-[.2em] text-rcl-orange">RCL SOCIAL</span><h2 className="mt-4 font-display text-4xl font-black uppercase">{tabs.find((item) => item.id === tab)?.label}</h2><p className="mt-3 text-sm leading-6 text-white/45">The Social platform connects people to basketball. Every section is designed to move naturally from conversation to discovery to participation.</p>{tab === 'runs' && <Link href="/runs" className="mt-6 inline-flex items-center gap-2 rounded-xl bg-rcl-orange px-4 py-3 text-[10px] font-black uppercase tracking-widest text-black">Open RCL Runs <FaArrowRight /></Link>}{tab === 'communities' && <Link href="/communities" className="mt-6 inline-flex items-center gap-2 rounded-xl bg-rcl-orange px-4 py-3 text-[10px] font-black uppercase tracking-widest text-black">Explore Communities <FaArrowRight /></Link>}{tab === 'messages' && <Link href="/messages" className="mt-6 inline-flex items-center gap-2 rounded-xl bg-rcl-orange px-4 py-3 text-[10px] font-black uppercase tracking-widest text-black">Open Messages <FaArrowRight /></Link>}{tab === 'notifications' && <Link href="/notifications" className="mt-6 inline-flex items-center gap-2 rounded-xl bg-rcl-orange px-4 py-3 text-[10px] font-black uppercase tracking-widest text-black">Open Notifications <FaArrowRight /></Link>}{tab === 'highlights' && <button onClick={() => { setTab('feed'); setFilter('highlights'); }} className="mt-6 inline-flex items-center gap-2 rounded-xl bg-rcl-orange px-4 py-3 text-[10px] font-black uppercase tracking-widest text-black">Browse feed highlights <FaArrowRight /></button>}{tab === 'discover' && <div className="mt-6"><SocialDiscoveryEmpty search="" profiles={suggestedProfiles} communities={communities} following={following} onFollow={(id) => void toggleFollow(id)} onCreate={openComposer} /></div>}</div></section>}</div>
      <aside className="hidden space-y-4 lg:block"><SideCard title="TRENDING IN THE 804"><div className="space-y-2">{trending.length ? trending.map(([word, count], index) => <button key={word} onClick={() => { setTab('feed'); setSearch(word); setFilter('all'); }} className="flex w-full items-center justify-between rounded-xl px-3 py-2 text-left hover:bg-white/[.04]"><span><span className="mr-2 text-[9px] text-white/25">0{index + 1}</span><span className="text-xs font-bold">#{word}</span></span><span className="text-[9px] text-white/25">{count} posts</span></button>) : <p className="px-3 py-2 text-xs text-white/30">Your city trends will appear here.</p>}</div></SideCard><SideCard title="ON THE COURTS"><div className="rounded-2xl border border-rcl-orange/20 bg-gradient-to-br from-rcl-orange/10 to-transparent p-4"><p className="text-[9px] font-black tracking-widest text-rcl-orange">LIVE SOCIAL LOOP</p><h3 className="mt-2 font-display text-xl font-black uppercase">Who&apos;s hooping?</h3><p className="mt-2 text-xs leading-5 text-white/40">Find a pickup run, join the player count and take the conversation from Social to the court.</p><Link href="/runs" className="mt-4 inline-flex items-center gap-2 text-[9px] font-black uppercase tracking-widest text-rcl-orange">Find a run <FaArrowRight /></Link></div></SideCard><SideCard title="KEEP EXPLORING"><div className="space-y-2"><ExploreLink href="/players" label="Player Directory" /><ExploreLink href="/games" label="Game Center" /><ExploreLink href="/lab" label="The Lab" /><ExploreLink href="/leaderboards" label="Leaderboards" /></div></SideCard></aside>
    </div></Container>
    <div className="rcl-social-tabs rcl-premium-bottom-nav fixed bottom-0 left-0 right-0 z-50 lg:hidden pb-[env(safe-area-inset-bottom)]"><div className="mx-auto grid max-w-xl grid-cols-5"><button onClick={() => { setTab('feed'); setFilter('all'); }} className={tab==='feed'?'active':''}><FaHouse/><span>Home</span></button><button onClick={() => selectTab('discover')} className={tab==='discover'?'active':''}><FaMagnifyingGlass/><span>Discover</span></button><button onClick={openComposer} className="create"><FaPlus/><span>Create</span></button><Link href="/notifications"><FaBell/><span>Alerts</span></Link>{user?<Link href={`/social/profile/${user.id}`}><FaUser/><span>Profile</span></Link>:<button onClick={signInForSocial}><FaUser/><span>Profile</span></button>}</div></div>
    {platformMenuOpen && <div className="fixed inset-0 z-[70] bg-black/70 backdrop-blur-sm" onClick={() => setPlatformMenuOpen(false)}><aside className="ml-auto flex h-full w-[min(88vw,360px)] flex-col border-l border-white/10 bg-[#090e15] p-5 shadow-2xl" onClick={(e) => e.stopPropagation()}><div className="flex items-center justify-between border-b border-white/10 pb-4"><div><p className="text-[9px] font-black uppercase tracking-[.22em] text-rcl-orange">Rich City League</p><h2 className="mt-1 font-display text-2xl font-black uppercase">Platform Menu</h2></div><button type="button" onClick={() => setPlatformMenuOpen(false)} aria-label="Close menu" className="grid h-10 w-10 place-items-center rounded-xl border border-white/10 text-white/60"><FaXmark /></button></div><nav className="mt-4 grid grid-cols-2 gap-2"><Link href="/" className="col-span-2 flex items-center gap-3 rounded-xl bg-rcl-orange px-4 py-3 text-xs font-black uppercase tracking-wider text-black"><FaHouse /> Exit Social · RCL Home</Link>{[{label:'My Profile',href:user ? `/social/profile/${user.id}` : '/auth/sign-in?redirect=/social'},{label:'Friends',href:'/friends'},{label:'Messages',href:'/messages'},{label:'Notifications',href:'/notifications'},{label:'Communities',href:'/communities'},{label:'Discover People',href:'/friends'},{label:'Saved Posts',href:'/social/saved'},{label:'My Stories',href:'/social/stories'},{label:'Photos & Videos',href:'/social/media'},{label:'Highlights',href:'/social/highlights'},{label:'Runs & Events',href:'/runs'},{label:'Social Settings',href:'/settings'}].map((item) => <Link key={item.href} href={item.href} className="rounded-xl border border-white/10 bg-white/[.03] px-3 py-3 text-xs font-bold text-white/70 hover:border-rcl-orange/40 hover:text-white">{item.label}</Link>)}</nav><div className="mt-auto border-t border-white/10 pt-4"><Link href="/profile" className="flex items-center gap-3 rounded-xl px-3 py-3 text-xs font-bold text-white/70">Edit My Profile</Link><Link href="/settings" className="flex items-center gap-3 rounded-xl px-3 py-3 text-xs font-bold text-white/70"><FaGear /> Settings</Link></div></aside></div>}
    {composerOpen && <div className="fixed inset-0 z-50 flex items-end justify-center bg-black/70 p-3 backdrop-blur-sm sm:items-center"><div className="w-full max-w-xl rounded-3xl border border-white/10 bg-[#0b1119] p-5 shadow-2xl"><div className="flex items-center justify-between"><div><p className="text-[9px] font-black tracking-[.2em] text-rcl-orange">CREATE ON RCL</p><h2 className="mt-1 font-display text-2xl font-black uppercase">Start the conversation</h2></div><button type="button" onClick={() => { setComposerOpen(false); setMediaFile(null); }} className="rounded-xl p-2 text-white/40 hover:bg-white/5" aria-label="Close composer"><FaXmark /></button></div><form onSubmit={createPost} className="mt-5"><textarea value={body} onChange={(e) => setBody(e.target.value)} autoFocus rows={5} maxLength={2000} placeholder="Share a game-day moment, run, opinion, highlight or shoutout…" className="w-full resize-none rounded-2xl border border-white/10 bg-black/20 p-4 text-sm outline-none focus:border-rcl-orange/50" /><input ref={mediaInputRef} type="file" accept="image/*,video/*" onChange={(e) => setMediaFile(e.target.files?.[0] ?? null)} className="hidden" /><div className="mt-3 flex flex-wrap gap-2"><SocialLinkField value={linkInput} onChange={setLinkInput} /><button type="button" onClick={() => mediaInputRef.current?.click()} className="inline-flex items-center gap-2 rounded-xl border border-white/10 bg-white/[.03] px-3 py-2 text-[9px] font-black uppercase tracking-wider text-white/55 hover:border-rcl-orange/30 hover:text-white"><FaImage /> Photo</button><button type="button" onClick={() => mediaInputRef.current?.click()} className="inline-flex items-center gap-2 rounded-xl border border-white/10 bg-white/[.03] px-3 py-2 text-[9px] font-black uppercase tracking-wider text-white/55 hover:border-rcl-orange/30 hover:text-white"><FaVideo /> Video</button></div>{mediaPreview && <div className="relative mt-3 overflow-hidden rounded-2xl border border-white/10 bg-black">{mediaFile?.type.startsWith('video/') ? <video src={mediaPreview} controls playsInline className="max-h-72 w-full object-contain" /> : <img src={mediaPreview} alt="Post preview" className="max-h-72 w-full object-contain" />}<button type="button" onClick={() => setMediaFile(null)} aria-label="Remove selected media" className="absolute right-2 top-2 rounded-lg bg-black/70 p-2 text-white"><FaXmark /></button></div>}<div className="mt-4 flex items-center justify-between"><span className="text-[9px] text-white/25">{body.length}/2000 {mediaFile ? `· ${Math.round(mediaFile.size / 1024 / 1024)}MB` : ''}</span><button disabled={(!body.trim() && !mediaFile && !linkInput.trim()) || publishing} className="inline-flex items-center gap-2 rounded-xl bg-rcl-orange px-5 py-3 text-[10px] font-black uppercase tracking-widest text-black disabled:opacity-30">{publishing ? 'Publishing…' : 'Publish'} <FaArrowRight /></button></div></form></div></div>}
    {storyIndex !== null && stories[storyIndex] && <StoryViewer stories={stories} index={storyIndex} onClose={() => setStoryIndex(null)} onIndexChange={(index) => { setStoryIndex(index); void viewStory(index); }} />}
    {error && error !== 'Social services are not configured.' && <div className="fixed bottom-20 left-1/2 z-[60] max-w-[calc(100vw-2rem)] -translate-x-1/2 rounded-xl border border-white/10 bg-[#101722] px-4 py-3 text-xs text-white shadow-xl">{error}</div>}
  </div></main></>;
}

function Avatar({ author }: { author?: Author }) {
  const rep = author?.rep ?? 0;
  const progress = Math.min(100, Math.max(4, (rep % 1000) / 10));
  return <span className={`rcl-rep-avatar ${author?.is_vip ? 'is-vip' : ''}`} style={{'--rep-progress': progress + '%'} as React.CSSProperties}>
    <span className="rcl-rep-avatar-core">{author?.avatar_url ? <img src={author.avatar_url} alt="" /> : <b>{(author?.display_name?.trim()?.[0] ?? 'R').toUpperCase()}</b>}</span>
    {(author?.level ?? 1) > 1 && <em>{author?.level}</em>}
  </span>;
}
function QuickAction({ icon, label, onClick }: { icon: React.ReactNode; label: string; onClick: () => void }) { return <button type="button" onClick={onClick} className="inline-flex items-center gap-2 rounded-xl border border-white/10 bg-black/10 px-3 py-2 text-[9px] font-black uppercase tracking-wider text-white/45 hover:border-rcl-orange/30 hover:text-white">{icon}<span>{label}</span></button>; }
function PostCard({ post, userId, following, saved, openComments, comment, onCommentChange, onToggleComments, onComment, onReact, reactionBurst, onSave, onShare, onFollow, onDelete }: { post: Post; userId?: string; following: boolean; saved: boolean; openComments: boolean; comment: string; onCommentChange: (value: string) => void; onToggleComments: () => void; onComment: () => void; onReact: (type: string) => void; reactionBurst: string | null; onSave: () => void; onShare: () => void; onFollow: () => void; onDelete?: () => void }) {
  const mine = post.reactions?.find((r) => r.user_id === userId); const reactionCount = post.reactions?.length ?? 0; const commentCount = post.comments?.length ?? 0; const profileHref = `/social/profile/${post.author_id}`;
  return <article id={`post-${post.id}`} className="rcl-premium-post mb-4 overflow-hidden rounded-3xl border border-white/10 bg-white/[.03]"><div className="flex items-start gap-3 p-4 sm:p-5"><Link href={profileHref} aria-label={`Open ${post.author?.display_name ?? 'RCL member'} profile`}><Avatar author={post.author} /></Link><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-3"><div><div className="flex flex-wrap items-center gap-2"><Link href={profileHref} className="text-sm font-black hover:text-rcl-orange">{post.author?.display_name ?? 'RCL Member'}</Link>{post.author?.is_vip&&<span className="rcl-vip-chip">♛ {post.author.vip_label||'VIP'}</span>}{post.author?.role && <span className="rounded-full bg-white/5 px-2 py-0.5 text-[8px] font-black uppercase tracking-widest text-white/30">{post.author.role}</span>}{following && <span className="text-[8px] font-black uppercase tracking-widest text-rcl-gold">Following</span>}</div><p className="mt-0.5 text-[10px] text-white/25"><span className="rcl-rep-copy">REP {formatRep(post.author?.rep ?? 0)} · LVL {post.author?.level ?? 1}</span> · {formatTime(post.created_at)}</p></div>{userId && post.author_id !== userId && <button type="button" onClick={onFollow} className={`rounded-lg border px-2.5 py-1.5 text-[8px] font-black uppercase tracking-widest ${following ? 'border-rcl-gold/30 text-rcl-gold' : 'border-white/10 text-white/40 hover:text-white'}`}>{following ? <><FaCheck className="mr-1 inline" />Following</> : 'Follow'}</button>}{onDelete && <button type="button" onClick={onDelete} className="rounded-lg p-2 text-white/20 hover:text-red-400" aria-label="Delete post"><FaTrash /></button>}</div><RichPostBody body={post.body} /></div></div>{post.media_urls?.[0] && <div className="border-y border-white/10 bg-black">{isVideoUrl(post.media_urls[0]) ? <video src={post.media_urls[0]} controls playsInline className="max-h-[520px] w-full object-contain" /> : <img src={post.media_urls[0]} alt="Post media" className="max-h-[520px] w-full object-cover" />}</div>}<div className="px-4 py-3 sm:px-5"><div className="flex items-center justify-between text-[9px] text-white/30"><span>{reactionCount ? `${reactionCount} ${reactionCount === 1 ? 'reaction' : 'reactions'}` : 'Be the first to react'}</span><button type="button" onClick={onToggleComments} className="hover:text-white">{commentCount} {commentCount === 1 ? 'comment' : 'comments'}</button></div><div className="mt-3 flex items-center gap-1 border-t border-white/5 pt-2">{reactions.slice(0, 4).map((reaction) => <button key={reaction.type} type="button" title={reaction.label} onClick={() => onReact(reaction.type)} className={`rcl-reaction rcl-reaction-${reaction.type} rounded-xl px-2.5 py-2 text-sm transition hover:bg-white/5 ${reactionBurst === reaction.type ? 'is-reacting' : ''} ${mine?.type === reaction.type ? 'bg-rcl-orange/10 ring-1 ring-rcl-orange/30' : ''}`}><span className="rcl-reaction-emoji" aria-hidden="true">{reaction.emoji}</span></button>)}<button type="button" onClick={onToggleComments} className="ml-1 inline-flex flex-1 items-center justify-center gap-2 rounded-xl py-2 text-[9px] font-black uppercase tracking-widest text-white/40 hover:bg-white/5 hover:text-white"><FaComment /> Comment</button><button type="button" onClick={onShare} className="rounded-xl p-2 text-white/40 hover:bg-white/5 hover:text-white" aria-label="Share post"><FaShareNodes /></button><button type="button" onClick={onSave} className={`rounded-xl p-2 ${saved ? 'text-rcl-gold' : 'text-white/40 hover:text-white'}`} aria-label={saved ? 'Unsave post' : 'Save post'}><FaBookmark /></button></div></div>{openComments && <div className="border-t border-white/10 bg-black/10 px-4 py-4 sm:px-5">{post.comments?.slice(-4).map((item) => <div key={item.id} className="mb-3 flex gap-2"><Link href={`/social/profile/${item.author_id}`} aria-label={`Open ${item.author?.display_name ?? 'RCL member'} profile`}><Avatar author={item.author} /></Link><div className="rounded-2xl bg-white/[.04] px-3 py-2"><Link href={`/social/profile/${item.author_id}`} className="text-[9px] font-black hover:text-rcl-orange">{item.author?.display_name ?? 'RCL Member'}</Link><p className="mt-1 text-xs leading-5 text-white/60">{item.body}</p></div></div>)}<form onSubmit={(e) => { e.preventDefault(); onComment(); }} className="flex gap-2"><input value={comment} onChange={(e) => onCommentChange(e.target.value)} placeholder="Add a reply…" className="min-w-0 flex-1 rounded-xl border border-white/10 bg-black/20 px-3 py-2.5 text-xs outline-none focus:border-rcl-orange/40" /><button disabled={!comment.trim()} className="rounded-xl bg-rcl-orange px-4 py-2 text-[9px] font-black uppercase tracking-widest text-black disabled:opacity-30">Send</button></form></div>}</article>;
}
function StoryViewer({ stories, index, onClose, onIndexChange }: { stories: Story[]; index: number; onClose: () => void; onIndexChange: (index: number) => void }) { const story = stories[index]; return <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/95 p-3"><div className="relative flex h-[min(760px,90vh)] w-full max-w-md flex-col overflow-hidden rounded-3xl border border-white/10 bg-gradient-to-br from-rcl-navy to-black shadow-2xl"><div className="absolute left-3 right-3 top-3 z-10 flex gap-1">{stories.map((_, i) => <span key={i} className={`h-1 flex-1 rounded-full ${i === index ? 'bg-white' : i < index ? 'bg-rcl-orange' : 'bg-white/20'}`} />)}</div><button onClick={onClose} className="absolute right-3 top-7 z-10 rounded-xl bg-black/30 p-2 text-white" aria-label="Close story"><FaXmark /></button><div className="flex flex-1 items-center justify-center p-8 text-center">{story.media_url ? <div className="w-full">{isVideoUrl(story.media_url) ? <video src={story.media_url} controls autoPlay playsInline className="max-h-[62vh] w-full rounded-2xl object-contain" /> : <img src={story.media_url} alt="Story" className="max-h-[62vh] w-full rounded-2xl object-contain" />}<p className="mt-4 text-lg font-bold leading-7 text-white">{story.body}</p></div> : <div><Avatar author={story.author} /><p className="mt-4 text-xl font-bold leading-8 text-white">{story.body || 'Game day in the 804.'}</p><p className="mt-4 text-[9px] font-black uppercase tracking-widest text-rcl-gold">RICH CITY SOCIAL · 24H</p></div>}</div><button aria-label="Previous story" disabled={index === 0} onClick={() => onIndexChange(index - 1)} className="absolute left-0 top-1/2 h-1/2 w-1/3 -translate-y-1/2 disabled:pointer-events-none" /><button aria-label="Next story" disabled={index === stories.length - 1} onClick={() => onIndexChange(index + 1)} className="absolute right-0 top-1/2 h-1/2 w-1/3 -translate-y-1/2 disabled:pointer-events-none" /><div className="border-t border-white/10 p-4 text-center text-[9px] font-black uppercase tracking-widest text-white/30">{index + 1} / {stories.length}</div></div></div>; }
function PulseMetric({ label, value, detail }: { label: string; value: number | string; detail: string }) {
  return <div className="rounded-2xl border border-white/10 bg-white/[.025] px-3 py-3">
    <p className="text-[8px] font-black tracking-[.16em] text-white/30">{label}</p>
    <p className="mt-1 font-display text-xl font-black text-white">{value}</p>
    <p className="mt-0.5 text-[8px] font-bold uppercase tracking-wider text-rcl-orange/70">{detail}</p>
  </div>;
}

function SideCard({ title, children }: { title: string; children: React.ReactNode }) { return <section className="rounded-3xl border border-white/10 bg-white/[.03] p-4"><p className="mb-3 text-[9px] font-black tracking-[.2em] text-white/35">{title}</p>{children}</section>; }
function ExploreLink({ href, label }: { href: string; label: string }) { return <Link href={href} className="flex items-center justify-between rounded-xl px-3 py-2.5 text-xs font-bold text-white/55 hover:bg-white/[.04] hover:text-white"><span>{label}</span><FaArrowRight className="text-[9px]" /></Link>; }
function LoadingFeed() { return <div className="space-y-4">{[1, 2, 3].map((item) => <div key={item} className="h-52 animate-pulse rounded-3xl border border-white/10 bg-white/[.03]" />)}</div>; }
function SocialDiscoveryEmpty({ search, profiles, communities, following, onFollow, onCreate }: { search: string; profiles: Author[]; communities: Community[]; following: string[]; onFollow: (id: string) => void; onCreate: () => void }) {
  if (search) return <div className="rcl-social-empty"><FaMagnifyingGlass /><h3>No matches</h3><p>No posts matched “{search}”. Try another search.</p></div>;
  return <div className="rcl-social-discovery-empty">
    <div className="rcl-empty-lead"><div><span>YOUR CITY · YOUR COURT</span><h3>The conversation starts here.</h3><p>Follow people, find a community or put the first post on the board.</p></div><button onClick={onCreate}><FaPlus /> Post</button></div>
    {profiles.length > 0 && <section><div className="rcl-discovery-heading"><div><small>REPUTATION</small><h4>People to watch</h4></div><Link href="/leaderboards">REP leaderboard <FaArrowRight /></Link></div><div className="rcl-profile-suggestions">{profiles.slice(0,4).map((profile) => <article key={profile.id}><Link href={`/social/profile/${profile.id}`}><Avatar author={profile} /><span><b>{profile.display_name || profile.username || 'RCL Member'}</b><small>{formatRep(profile.rep ?? 0)} REP · LVL {profile.level ?? 1}</small></span></Link>{profile.id && <button onClick={() => onFollow(profile.id!)}>{following.includes(profile.id) ? 'Following' : 'Follow'}</button>}</article>)}</div></section>}
    {communities.length > 0 && <section><div className="rcl-discovery-heading"><div><small>COMMUNITIES</small><h4>Find your people</h4></div><Link href="/communities">See all <FaArrowRight /></Link></div><div className="rcl-community-suggestions">{communities.slice(0,3).map((community) => <Link href="/communities" key={community.id}><FaPeopleGroup /><span><b>{community.name}</b><small>{community.description || 'RCL basketball community'}</small></span><FaArrowRight /></Link>)}</div></section>}
    <div className="rcl-empty-shortcuts"><Link href="/runs"><FaBasketball /><span><b>Find a run</b><small>Get on the court</small></span></Link><Link href="/players"><FaUserGroup /><span><b>Players</b><small>Explore the city</small></span></Link><Link href="/games"><FaPlay /><span><b>Game Center</b><small>Follow the action</small></span></Link></div>
  </div>;
}
function isVideoUrl(url: string) { return /\.(mp4|webm|mov|m4v)(\?|$)/i.test(url); }
function formatRep(value:number){return value>=1000?(value/1000).toFixed(1)+"K":String(value);}
function formatTime(value: string) { const date = new Date(value); const diff = Math.max(0, Date.now() - date.getTime()); const mins = Math.floor(diff / 60000); if (mins < 1) return 'Just now'; if (mins < 60) return `${mins}m`; const hours = Math.floor(mins / 60); if (hours < 24) return `${hours}h`; return `${Math.floor(hours / 24)}d`; }
